presets.css:
/* ==========================================
   【长夜＆机械之心】夜间版 - 纯黑方形底栏
   作者：长夜何其多（禁二改二传商用）
   ========================================== */

/* 1. 全局背景：直接使用暗黑星空图 */
.chat-app, .chat-inbox, .chat-scroll {
  background-color: #000000 !important; 
  background-image: url('https://picui.ogmua.cn/s1/2026/11/08/6aefd141288ba.webp') !important; /* 换成了另一个黑图 */
  background-size: cover !important; 
  background-position: center !important; 
  background-repeat: no-repeat !important; 
}

/* 2. 顶栏：位置往上提 + 往右移 + 取消重影 */
.chat-head-inbox { 
  background: transparent !important; 
  box-shadow: none !important; 
  padding: 10px 16px 0 16px !important; 
}
.chat-inbox-title, 
[class*="inbox-title"], 
.chat-head-inbox h1, 
.chat-head-inbox h2,
.chat-head-inbox [class*="title"] {
  color: #ffffff !important; 
  font-family: 'Cinzel', 'Songti SC', serif !important;
  font-weight: 700 !important; 
  letter-spacing: 2px !important;
  font-size: 24px !important; 
  display: inline-block !important; 
  transform: translate(15px, -20px) !important; 
  text-shadow: none !important; 
}

/* 切换器 */
.chat-inbox-filter button {
  background: transparent !important;
  color: #666666 !important;
  border-radius: 0 !important; 
  border: 1px solid #333333 !important;
  transform: translateY(-8px) !important; 
}
.chat-inbox-filter button.on {
  background: #ffffff !important;
  color: #000000 !important;
  border: 1px solid #ffffff !important;
  box-shadow: 0 0 12px rgba(255,255,255,0.6) !important;
}

/* ==========================================
   核心：黑玻璃面板（调透一点，让黑星空透出来）
   ========================================== */
.chat-list-sheet {
  background: rgba(5, 5, 5, 0.65) !important; /* 降低不透明度，让背景星空透过来 */
  backdrop-filter: blur(20px) !important; 
  -webkit-backdrop-filter: blur(20px) !important;

  border-radius: 0 !important; 
  margin: 25px 16px 35px 16px !important; 
  padding: 10px !important; 
  overflow: visible !important; 

  border: 1px solid #333 !important;
  box-shadow: 0 10px 30px rgba(0,0,0,0.8) !important;
  position: relative !important;
}

/* 【顶部心电图】 - 纯白色流动 */
.chat-list-sheet::before {
  content: "" !important;
  position: absolute !important;
  top: -18px !important; 
  left: 0 !important;
  right: 0 !important;
  height: 16px !important;
  background-image: url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 20" preserveAspectRatio="none"><path d="M0 15 L10 15 L15 15 L18 5 L22 18 L25 10 L28 15 L40 15 L43 12 L46 15 L60 15 L63 5 L67 18 L70 10 L73 15 L85 15 L88 12 L91 15 L100 15" fill="none" stroke="%23ffffff" stroke-width="1.5" opacity="0.9"/></svg>') !important;
  background-size: 120px 16px !important; 
  background-repeat: repeat-x !important;
  animation: row-ecg-night 3s linear infinite !important;
  z-index: 99 !important;
}

/* 【底部心电图】 - 纯白色反向流动 */
.chat-list-sheet::after {
  content: "" !important;
  position: absolute !important;
  bottom: -18px !important; 
  left: 0 !important;
  right: 0 !important;
  height: 16px !important;
  background-image: url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 20" preserveAspectRatio="none"><path d="M0 15 L10 15 L15 15 L18 5 L22 18 L25 10 L28 15 L40 15 L43 12 L46 15 L60 15 L63 5 L67 18 L70 10 L73 15 L85 15 L88 12 L91 15 L100 15" fill="none" stroke="%23ffffff" stroke-width="1.5" opacity="0.9"/></svg>') !important;
  background-size: 120px 16px !important; 
  background-repeat: repeat-x !important;
  animation: row-ecg-reverse-night 3s linear infinite !important;
  z-index: 99 !important;
}

@keyframes row-ecg-night { 
  0% { background-position: 0 0; } 
  100% { background-position: -120px 0; } 
}
@keyframes row-ecg-reverse-night { 
  0% { background-position: 0 0; } 
  100% { background-position: 120px 0; } 
}

/* ==========================================
   白色跳动的爱心
   ========================================== */
.chat-row-wrap:first-child {
  position: relative !important;
}
.chat-row-wrap:first-child::before {
  content: '♥' !important;
  position: absolute !important;
  top: -33px !important; 
  left: 10% !important;
  font-size: 16px !important;
  color: #ffffff !important; 
  text-shadow: 0 0 6px rgba(255, 255, 255, 0.9) !important; 
  z-index: 999 !important; 
  pointer-events: none !important;
  animation: heart-walk-night 4s ease-in-out infinite alternate !important;
}

@keyframes heart-walk-night {
  0%   { left: 4%; transform: translateY(0) scale(1); }
  30%  { transform: translateY(-4px) scale(1.15); } 
  60%  { transform: translateY(0) scale(1); }
  80%  { transform: translateY(-4px) scale(1.15); } 
  100% { left: 96%; transform: translateY(0) scale(1); }
}

/* ==========================================
   内部：白色卡片 + 黑字
   ========================================== */
.chat-row-wrap {
  background: transparent !important;
  border-bottom: none !important;
  margin-bottom: 8px !important; 
}
.chat-row-wrap:last-child {
  margin-bottom: 0 !important;
}

.chat-row {
  background: rgba(255, 255, 255, 0.95) !important; 
  position: relative !important;
  padding: 14px 16px !important; 
  border: 1px solid #e0e0e0 !important;
  border-radius: 4px !important; 
  box-shadow: 0 2px 8px rgba(0,0,0,0.2) !important;
}

.chat-row * {
  color: #000000 !important;
}

.chat-row-top strong {
  color: #000000 !important;
  font-family: 'Cinzel', 'Songti SC', serif !important;
  font-weight: 700 !important;
  font-size: 16px !important;
  letter-spacing: 1px !important;
}

.chat-row-preview {
  color: #444444 !important; 
  font-family: 'Songti SC', 'STSong', serif !important;
  font-size: 13px !important;
  margin-top: 2px !important;
}

.chat-row-meta { 
  color: #888888 !important; 
  font-family: 'Cinzel', serif !important;
  font-size: 11px !important; 
}

.chat-ava-list {
  border-radius: 4px !important; 
  border: 1.5px solid #000000 !important; 
  background: #ffffff !important;
  box-shadow: inset 0 0 0 1px rgba(255,255,255,1) !important; 
  padding: 1px !important;
}
.chat-ava-list img { border-radius: 2px !important; }

.chat-row-unread {
  background: #ffffff !important; 
  color: #000000 !important;      
  border-radius: 0 !important;    
  border: 2px solid #000000 !important; 
  font-weight: 900 !important;
  box-shadow: 2px 2px 0px rgba(0, 0, 0, 0.8) !important; 
}

.chat-row-pin-mark {
  background: #000000 !important;
  color: #ffffff !important;
  border: none !important;
  border-radius: 0 !important;
}

/* ==========================================
   底部导航栏美化（纯黑底 + 强制方形）
   ========================================== */
.chat-tabdock {
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
}

/* 外壳容器强制纯黑 */
.chat-tabdock-pill {
  background: #000000 !important; 
  backdrop-filter: blur(20px) !important;
  border: 1px solid #333333 !important;
  border-radius: 0 !important; 
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.9) !important;
  padding: 6px !important; 
}

.chat-tabdock-pill * {
  color: #888888 !important; 
  fill: #888888 !important; 
  border-radius: 0 !important; 
}

/* 选中态：白底黑字 */
.chat-tabdock-pill .on,
.chat-tabdock-pill .active,
.chat-tabdock-pill > div:first-child,
.chat-tabdock-pill > button:first-child {
  background: #ffffff !important;
  box-shadow: 0 0 15px rgba(255, 255, 255, 0.3) !important;
  border-radius: 0 !important;
}

.chat-tabdock-pill .on *,
.chat-tabdock-pill .active *,
.chat-tabdock-pill > div:first-child *,
.chat-tabdock-pill > button:first-child * {
  color: #000000 !important;
  fill: #000000 !important;
}

/* 未选中态：纯黑底 + 灰边框 */
.chat-tabdock-pill > div:not(.on):not(.active),
.chat-tabdock-pill > button:not(.on):not(.active) {
  background: #000000 !important; 
  border: 1px solid #333333 !important; 
  border-radius: 0 !important;
  margin: 0 4px !important; 
}
